PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?birthDate
WHERE {
  VALUES ?film { dbr:Speed_Walking dbr:Gie }

  # director (prefer dbp:director, fallback to dbo:director)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?director . }

  # birth date (prefer dbp:birthDate, fallback to dbo:birthDate)
  OPTIONAL { ?director dbp:birthDate ?bdate . }
  OPTIONAL { ?director dbo:birthDate ?bdate2 . }
  BIND (COALESCE(?bdate, ?bdate2) AS ?birthDate)
}
LIMIT 100
